"import pandas as pd
import os

DATA_DIR = os.path.abspath(os.path.join(os.path.dirname(__file__), ""))

def _load_csv(filename: str) -> pd.DataFrame:
    """Load a CSV file from the repository root.

    Parameters
    ----------
    filename: str
        Name of the CSV file (e.g., 'teams.csv').
    """
    path = os.path.join(DATA_DIR, filename)
    if not os.path.exists(path):
        raise FileNotFoundError(f"{filename} not found at {path}")
    return pd.read_csv(path)


def get_teams() -> pd.DataFrame:
    """Return DataFrame of all teams."""
    return _load_csv("teams.csv")


def get_players() -> pd.DataFrame:
    """Return DataFrame of all players."""
    return _load_csv("players.csv")


def get_umpires() -> pd.DataFrame:
    """Return DataFrame of all umpires (if file exists)."""
    try:
        return _load_csv("umpires.csv")
    except FileNotFoundError:
        return pd.DataFrame(columns=["umpire_id", "umpire_name"])


def get_venues() -> pd.DataFrame:
    """Return DataFrame of all venues."""
    return _load_csv("venues.csv")
