"import streamlit as st
from query_helper import get_teams

def show_teams():
    """Display a table of all IPL teams."""
    st.title('All IPL Teams')
    try:
        df = get_teams()
        if df.empty:
            st.warning('No team data available.')
        else:
            st.dataframe(df)
    except Exception as e:
        st.error(f'Error loading teams: {e}')
